def eprint(s=""):
    sys.stderr.write(s)


def c_atoi(s, default=0):
    if s is None:
        return default
    s = str(s).lstrip()
    m = re.match(r'([+-]?\d+)', s)
    if not m:
        return 0
    try:
        return int(m.group(1))
    except Exception:
        return default


def c_atof(s, default=0.0):
    if s is None:
        return default
    s = str(s).lstrip()
    m = re.match(r'([+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?)', s)
    if not m:
        return 0.0
    try:
        return float(m.group(1))
    except Exception:
        return default


class MT19937_64:
    """std::mt19937_64 compatible engine."""
    NN = 312
    MM = 156
    MATRIX_A = 0xB5026F5AA96619E9
    UM = 0xFFFFFFFF80000000
    LM = 0x7FFFFFFF

    def __init__(self, seed=5489):
        self.mt = [0] * self.NN
        self.mti = self.NN + 1
        self.seed(seed)

    def seed(self, seed):
        seed &= MASK64
        self.mt[0] = seed
        for i in range(1, self.NN):
            self.mt[i] = (6364136223846793005 * (self.mt[i-1] ^ (self.mt[i-1] >> 62)) + i) & MASK64
        self.mti = self.NN

    def _twist(self):
        mag01 = [0, self.MATRIX_A]
        for i in range(0, self.NN - self.MM):
            x = (self.mt[i] & self.UM) | (self.mt[i+1] & self.LM)
            self.mt[i] = (self.mt[i+self.MM] ^ (x >> 1) ^ mag01[x & 1]) & MASK64
        for i in range(self.NN - self.MM, self.NN - 1):
            x = (self.mt[i] & self.UM) | (self.mt[i+1] & self.LM)
            self.mt[i] = (self.mt[i+(self.MM-self.NN)] ^ (x >> 1) ^ mag01[x & 1]) & MASK64
        x = (self.mt[self.NN-1] & self.UM) | (self.mt[0] & self.LM)
        self.mt[self.NN-1] = (self.mt[self.MM-1] ^ (x >> 1) ^ mag01[x & 1]) & MASK64
        self.mti = 0

    def rand64(self):
        if self.mti >= self.NN:
            self._twist()
        x = self.mt[self.mti]
        self.mti += 1
        x ^= (x >> 29) & 0x5555555555555555
        x ^= (x << 17) & 0x71D67FFFEDA60000
        x ^= (x << 37) & 0xFFF7EEE000000000
        x ^= (x >> 43)
        return x & MASK64

    def random(self):
        return self.rand64() / 18446744073709551616.0


@dataclass
class Record:
    name: str
    comment: str
    seq: str
    qual: str = None

    @property
    def is_fastq(self):
        return self.qual is not None

    def header(self):
        return self.name + ((" " + self.comment) if self.comment else "")


def split_header(h):
    h = h.rstrip('\r\n')
    if not h:
        return "", ""
    parts = h.split(None, 1)
    if len(parts) == 1:
        return parts[0], ""
    return parts[0], parts[1]


def read_text(path):
    if path is None or path == "-":
        return sys.stdin.read()
    try:
        if str(path).endswith('.gz'):
            with gzip.open(path, 'rt', encoding='latin-1', newline=None) as f:
                return f.read()
        with open(path, 'r', encoding='latin-1', newline=None) as f:
            return f.read()
    except Exception:
        return None


def load_records(path, tag=None, period=True):
    txt = read_text(path)
    if txt is None:
        if tag:
            eprint(f"[E::{tag}] failed to open the input file/stream" + (".\n" if period else "\n"))
        return None
    return parse_records(txt)


def parse_records(txt):
    lines = txt.splitlines()
    records = []
    i = 0
    n = len(lines)
    while i < n and not (lines[i].startswith('>') or lines[i].startswith('@')):
        i += 1
    if i >= n:
        return records
    first = lines[i][0]
    if first == '>':
        while i < n:
            if not lines[i].startswith('>'):
                i += 1
                continue
            name, comment = split_header(lines[i][1:])
            i += 1
            seq_parts = []
            while i < n and not lines[i].startswith('>'):
                # kseq removes whitespace around sequence lines. Keep internal characters.
                seq_parts.append(lines[i].strip())
                i += 1
            records.append(Record(name, comment, ''.join(seq_parts), None))
    else:
        while i < n:
            if not lines[i].startswith('@'):
                i += 1
                continue
            name, comment = split_header(lines[i][1:])
            i += 1
            seq_parts = []
            while i < n and not lines[i].startswith('+'):
                seq_parts.append(lines[i].strip())
                i += 1
            seq = ''.join(seq_parts)
            if i < n and lines[i].startswith('+'):
                i += 1
            qual_parts = []
            qlen = 0
            while i < n and qlen < len(seq):
                qline = lines[i].rstrip('\r\n')
                qual_parts.append(qline)
                qlen += len(qline)
                i += 1
            qual = ''.join(qual_parts)[:len(seq)]
            records.append(Record(name, comment, seq, qual))
    return records


_COMP_TABLE = str.maketrans({
    'A':'T','C':'G','G':'C','T':'A','U':'A','R':'Y','Y':'R','S':'S','W':'W','K':'M','M':'K','B':'V','D':'H','H':'D','V':'B','N':'N',
    'a':'t','c':'g','g':'c','t':'a','u':'a','r':'y','y':'r','s':'s','w':'w','k':'m','m':'k','b':'v','d':'h','h':'d','v':'b','n':'n'
})

def revcomp(seq):
    return seq.translate(_COMP_TABLE)[::-1]


def wrap(s, line_len):
    if line_len and line_len > 0:
        return '\n'.join(s[i:i+line_len] for i in range(0, len(s), line_len)) + '\n' if s else '\n'
    return s + '\n'


def write_record(rec, seq=None, qual=None, force_fasta=False, line_len=0, header=None, drop_comment=False, fileobj=None):
    if fileobj is None:
        fileobj = sys.stdout
    if seq is None:
        seq = rec.seq
    if qual is None:
        qual = rec.qual
    if header is None:
        header = rec.name if drop_comment else rec.header()
    if force_fasta or qual is None:
        fileobj.write('>' + header + '\n')
        fileobj.write(wrap(seq, line_len))
    else:
        fileobj.write('@' + header + '\n')
        fileobj.write(wrap(seq, line_len))
        fileobj.write('+\n')
        fileobj.write(wrap(qual, line_len))


def parse_short_options(argv, spec, prog, print_errors=True):
    """GNU-getopt-like short option scan with permutation of non-options."""
    opts = []
    rest = []
    invalid = []
    missing = []
    i = 0
    stop = False
    while i < len(argv):
        arg = argv[i]
        if stop or arg == '-' or not (len(arg) > 1 and arg.startswith('-')):
            rest.append(arg)
            i += 1
            continue
        if arg == '--':
            rest.extend(argv[i+1:])
            break
        j = 1
        while j < len(arg):
            ch = arg[j]
            if ch not in spec:
                invalid.append(ch)
                if print_errors:
                    eprint(f"{prog}: invalid option -- '{ch}'\n")
                j += 1
                continue
            need = spec[ch]
            if need:
                if j + 1 < len(arg):
                    val = arg[j+1:]
                    opts.append((ch, val))
                    j = len(arg)
                else:
                    if i + 1 < len(argv):
                        i += 1
                        opts.append((ch, argv[i]))
                    else:
                        missing.append(ch)
                        if print_errors:
                            eprint(f"{prog}: option requires an argument -- '{ch}'\n")
                    break
            else:
                opts.append((ch, None))
                j += 1
        i += 1
    return opts, rest, invalid, missing


def load_mask_regions(path):
    txt = read_text(path)
    regs = defaultdict(list)
    if txt is None:
        return regs
    for line in txt.splitlines():
        if not line or line.startswith('#'):
            continue
        t = line.split()
        if not t:
            continue
        name = t[0]
        if len(t) >= 2 and re.match(r'^[+-]?\d+$', t[1]):
            b = int(t[1])
            if b < 0:
                regs[name].append(None)
                continue
            if len(t) >= 3 and re.match(r'^[+-]?\d+$', t[2]):
                e = int(t[2])
            else:
                e = None
            regs[name].append((b, e))
        else:
            regs[name].append(None)
    return regs


def apply_region_mask(seq, entries):
    if not entries:
        return seq
    arr = list(seq)
    L = len(arr)
    for ent in entries:
        if ent is None:
            for i in range(L):
                arr[i] = arr[i].lower()
        else:
            b, e = ent
            if e is None or e > L:
                e = L
            if b < 0:
                b = 0
            if e < b:
                continue
            for i in range(b, min(e, L)):
                arr[i] = arr[i].lower()
    return ''.join(arr)


def q_error_prob(qv):
    if qv <= 0:
        return 0.5
    return 10 ** (-qv / 10.0)


def cmd_seq(argv):
    spec = {c: False for c in 'aACrRUNx12'}
    for c in 'lqQnfsLMFX':
        spec[c] = True
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'seq')
    out_fasta = False
    drop_comment = False
    rev = False
    both = False
    upper = False
    dropN = False
    line_len = 0
    q_thr = None
    q_off = 33
    n_char = None
    frac = 1.0
    seed = 11
    min_len = 0
    mask_file = None
    fixed_qual = None
    x_thr = None
    pair_mode = 0
    for ch, val in opts:
        if ch in ('a', 'A'):
            out_fasta = True
        elif ch == 'C':
            drop_comment = True
        elif ch == 'r':
            rev = True
        elif ch == 'R':
            both = True
        elif ch == 'U':
            upper = True
        elif ch == 'N':
            dropN = True
        elif ch == 'l':
            line_len = c_atoi(val)
        elif ch == 'q':
            q_thr = c_atoi(val)
        elif ch == 'Q':
            q_off = c_atoi(val)
        elif ch == 'n':
            n_char = val[0] if val else ''
        elif ch == 'f':
            frac = c_atof(val, 1.0)
        elif ch == 's':
            seed = c_atoi(val, 11)
        elif ch == 'L':
            min_len = c_atoi(val)
        elif ch == 'M':
            mask_file = val
        elif ch == 'F':
            fixed_qual = val[0] if val else ''
        elif ch == 'X':
            x_thr = c_atoi(val)
        elif ch == '1':
            pair_mode = 1
        elif ch == '2':
            pair_mode = 2
        elif ch == 'x':
            pass
    path = rest[0] if rest else None
    records = load_records(path, 'stk_seq')
    if records is None:
        return 1
    masks = load_mask_regions(mask_file) if mask_file else {}
    rng = MT19937_64(seed)
    for idx, rec in enumerate(records, 1):
        if pair_mode == 1 and idx % 2 == 0:
            continue
        if pair_mode == 2 and idx % 2 == 1:
            continue
        if min_len and len(rec.seq) < min_len:
            continue
        if dropN and any(ch.upper() not in ('A','C','G','T') for ch in rec.seq):
            continue
        if frac < 1.0 or frac == 0.0:
            if not (rng.random() < frac):
                continue
        seq = rec.seq.upper() if upper else rec.seq
        if mask_file:
            seq = apply_region_mask(seq, masks.get(rec.name, []))
        qual = rec.qual
        if fixed_qual is not None and qual is not None:
            qual = fixed_qual * len(seq)
        if q_thr is not None and rec.qual is not None:
            arr = list(seq)
            for i, qc in enumerate(rec.qual[:len(arr)]):
                qv = ord(qc) - q_off
                mask = qv < q_thr
                if x_thr is not None:
                    mask = (qv <= q_thr) or (qv >= x_thr)
                if mask:
                    arr[i] = n_char if n_char is not None else arr[i].lower()
            seq = ''.join(arr)
        def header_with_suffix(suf):
            base = rec.name + suf
            if (not drop_comment) and rec.comment:
                base += ' ' + rec.comment
            return base
        if both:
            write_record(rec, seq=seq, qual=qual, force_fasta=out_fasta, line_len=line_len, header=header_with_suffix('+'))
            rseq = revcomp(seq)
            rqual = qual[::-1] if qual is not None else None
            write_record(rec, seq=rseq, qual=rqual, force_fasta=out_fasta, line_len=line_len, header=header_with_suffix('-'))
        else:
            if rev:
                seq = revcomp(seq)
                if qual is not None:
                    qual = qual[::-1]
            header = rec.name if drop_comment else rec.header()
            write_record(rec, seq=seq, qual=qual, force_fasta=out_fasta, line_len=line_len, header=header)
    return 0


