def cmd_fqchk(argv):
    spec = {'q': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'fqchk')
    qthres = 20
    for ch, val in opts:
        if ch == 'q': qthres = c_atoi(val)
    if invalid or missing or len(rest) < 1:
        eprint(FQCHK_USAGE)
        return 1
    records = load_records(rest[0], 'stk_fqchk')
    if records is None:
        return 1
    if not records:
        sys.stdout.write("min_len: 0; max_len: 0; avg_len: 0.00; 0 distinct quality values\n")
        return 0
    max_len = max(len(r.seq) for r in records)
    min_len = min(len(r.seq) for r in records)
    total_len = sum(len(r.seq) for r in records)
    per = []
    for _ in range(max_len+1):
        per.append({'bases':0,'base':[0,0,0,0,0],'qsum':0.0,'err':0.0,'low':0,'high':0,'qcnt':Counter()})
    qset = set()
    def add_stat(st, base, qv):
        st['bases'] += 1
        u = base.upper()
        if u == 'A': st['base'][0]+=1
        elif u == 'C': st['base'][1]+=1
        elif u == 'G': st['base'][2]+=1
        elif u == 'T': st['base'][3]+=1
        else: st['base'][4]+=1
        st['qsum'] += qv
        st['err'] += q_error_prob(qv)
        if qv < qthres: st['low'] += 1
        else: st['high'] += 1
        st['qcnt'][qv] += 1
    for rec in records:
        if rec.qual is None:
            continue
        for i, (b, qch) in enumerate(zip(rec.seq, rec.qual), 1):
            qv = ord(qch) - 33
            qset.add(qv)
            add_stat(per[0], b, qv)
            add_stat(per[i], b, qv)
    sys.stdout.write(f"min_len: {min_len}; max_len: {max_len}; avg_len: {total_len/len(records):.2f}; {len(qset)} distinct quality values\n")
    qvals = sorted(qset)
    if qthres == 0:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ" + ''.join(f"\t%Q{q}" for q in qvals) + "\n")
    else:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
    def out_line(label, st):
        n = st['bases']
        if n == 0:
            return
        pcts = [100.0*x/n for x in st['base']]
        avgq = st['qsum']/n
        errq = -10.0*math.log10(st['err']/n) if st['err'] > 0 else 99.0
        s = f"{label}\t{n}" + ''.join(f"\t{x:.1f}" for x in pcts) + f"\t{avgq:.1f}\t{errq:.1f}"
        if qthres == 0:
            s += ''.join(f"\t{(100.0*st['qcnt'].get(q,0)/n):.2f}" for q in qvals)
        else:
            s += f"\t{100.0*st['low']/n:.1f}\t{100.0*st['high']/n:.1f}"
        sys.stdout.write(s + "\n")
    out_line('ALL', per[0])
    for i in range(1, max_len+1):
        out_line(str(i), per[i])
    return 0


def cmd_sample(argv):
    spec = {'2': False, 's': True}
