    twopass = False
    seed = 11
    for ch, val in opts:
        if ch == '2': twopass = True
        elif ch == 's': seed = c_atoi(val, 11)
    if missing or len(rest) < 2:
        eprint(SAMPLE_USAGE)
        return 1
    records = load_records(rest[0], 'stk_sample')
    if records is None:
        return 1
    val = c_atof(rest[1])
    rng = MT19937_64(seed)
    if val < 1.0:
        for rec in records:
            if rng.random() < val:
                write_record(rec)
        return 0
    k = int(val)
    if k <= 0:
        return 0
    if k >= len(records):
        for rec in records:
            write_record(rec)
        return 0
    reservoir = []
    selected_ids = set()
    for idx, rec in enumerate(records, 1):
        raw = rng.rand64()
        if len(reservoir) < k:
            reservoir.append(rec)
        else:
            j = (raw * idx) >> 64
            if j < k:
                reservoir[j] = rec
    if twopass:
        selected_ids = {id(r) for r in reservoir}
        for rec in records:
            if id(rec) in selected_ids:
                write_record(rec)
    else:
        for rec in reservoir:
            write_record(rec)
    return 0


