BASE_MASKS = {
    'A':1, 'C':2, 'G':4, 'T':8,
    'R':1|4, 'Y':2|8, 'S':2|4, 'W':1|8, 'K':4|8, 'M':1|2,
    'B':2|4|8, 'D':1|4|8, 'H':1|2|8, 'V':1|2|4,
}

def cmd_comp(argv):
    spec = {'r': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'comp')
    path = rest[0] if rest else None
    records = load_records(path, 'stk_comp')
    if records is None:
        return 1
    for rec in records:
        cols = [0]*11
        masks = []
        chars = []
        for ch in rec.seq:
            u = ch.upper()
            chars.append(u)
            if u == 'A': cols[0]+=1; masks.append(1)
            elif u == 'C': cols[1]+=1; masks.append(2)
            elif u == 'G': cols[2]+=1; masks.append(4)
            elif u == 'T': cols[3]+=1; masks.append(8)
            elif u in ('R','Y','S','W','K','M'):
                cols[4]+=1; masks.append(BASE_MASKS[u])
                if u in ('R','Y'):
                    cols[9]+=1
                else:
                    cols[8]+=1
            elif u in ('B','D','H','V'):
                cols[5]+=1; masks.append(BASE_MASKS[u])
            else:
                cols[6]+=1; masks.append(0)
        for i in range(len(masks)-1):
            if (masks[i] & 2) and (masks[i+1] & 4):
                cols[7] += 2
            if chars[i] == 'Y' and (masks[i+1] & 4):
                cols[10] += 1
            if (masks[i] & 2) and chars[i+1] == 'R':
                cols[10] += 1
        sys.stdout.write(rec.name + '\t' + str(len(rec.seq)) + ''.join('\t'+str(x) for x in cols) + '\n')
    return 0


def cmd_fqchk(argv):
    spec = {'q': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'fqchk')
    qthres = 20
    for ch, val in opts:
        if ch == 'q': qthres = c_atoi(val)
    if invalid or missing or len(rest) < 1:
        eprint(FQCHK_USAGE)
        return 1
    records = load_records(rest[0], 'stk_fqchk')
    if records is None:
        return 1
    if not records:
        sys.stdout.write("min_len: 0; max_len: 0; avg_len: 0.00; 0 distinct quality values\n")
        return 0
    max_len = max(len(r.seq) for r in records)
    min_len = min(len(r.seq) for r in records)
    total_len = sum(len(r.seq) for r in records)
    per = []
    for _ in range(max_len+1):
        per.append({'bases':0,'base':[0,0,0,0,0],'qsum':0.0,'err':0.0,'low':0,'high':0,'qcnt':Counter()})
    qset = set()
    def add_stat(st, base, qv):
        st['bases'] += 1
        u = base.upper()
        if u == 'A': st['base'][0]+=1
        elif u == 'C': st['base'][1]+=1
        elif u == 'G': st['base'][2]+=1
        elif u == 'T': st['base'][3]+=1
        else: st['base'][4]+=1
        st['qsum'] += qv
        st['err'] += q_error_prob(qv)
        if qv < qthres: st['low'] += 1
        else: st['high'] += 1
        st['qcnt'][qv] += 1
    for rec in records:
        if rec.qual is None:
            continue
        for i, (b, qch) in enumerate(zip(rec.seq, rec.qual), 1):
            qv = ord(qch) - 33
            qset.add(qv)
            add_stat(per[0], b, qv)
            add_stat(per[i], b, qv)
    sys.stdout.write(f"min_len: {min_len}; max_len: {max_len}; avg_len: {total_len/len(records):.2f}; {len(qset)} distinct quality values\n")
    qvals = sorted(qset)
    if qthres == 0:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ" + ''.join(f"\t%Q{q}" for q in qvals) + "\n")
    else:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
    def out_line(label, st):
        n = st['bases']
        if n == 0:
            return
        pcts = [100.0*x/n for x in st['base']]
        avgq = st['qsum']/n
        errq = -10.0*math.log10(st['err']/n) if st['err'] > 0 else 99.0
        s = f"{label}\t{n}" + ''.join(f"\t{x:.1f}" for x in pcts) + f"\t{avgq:.1f}\t{errq:.1f}"
        if qthres == 0:
            s += ''.join(f"\t{(100.0*st['qcnt'].get(q,0)/n):.2f}" for q in qvals)
        else:
            s += f"\t{100.0*st['low']/n:.1f}\t{100.0*st['high']/n:.1f}"
        sys.stdout.write(s + "\n")
    out_line('ALL', per[0])
    for i in range(1, max_len+1):
        out_line(str(i), per[i])
    return 0


def cmd_sample(argv):
    spec = {'2': False, 's': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'sample')
    twopass = False
    seed = 11
    for ch, val in opts:
        if ch == '2': twopass = True
        elif ch == 's': seed = c_atoi(val, 11)
    if missing or len(rest) < 2:
        eprint(SAMPLE_USAGE)
        return 1
    records = load_records(rest[0], 'stk_sample')
    if records is None:
        return 1
    val = c_atof(rest[1])
    rng = MT19937_64(seed)
    if val < 1.0:
        for rec in records:
            if rng.random() < val:
                write_record(rec)
        return 0
    k = int(val)
    if k <= 0:
        return 0
    if k >= len(records):
        for rec in records:
            write_record(rec)
        return 0
    reservoir = []
    selected_ids = set()
    for idx, rec in enumerate(records, 1):
        raw = rng.rand64()
        if len(reservoir) < k:
            reservoir.append(rec)
        else:
            j = (raw * idx) >> 64
            if j < k:
                reservoir[j] = rec
    if twopass:
        selected_ids = {id(r) for r in reservoir}
        for rec in records:
            if id(rec) in selected_ids:
                write_record(rec)
    else:
        for rec in reservoir:
            write_record(rec)
    return 0


@dataclass
class SubEntry:
    kind: str   # 'name' or 'region'
    beg: int = 0
    end: int = None
    strand: str = '+'


def parse_subseq_list(path):
    txt = read_text(path)
    if txt is None:
        return None
    entries = defaultdict(list)
    for line in txt.splitlines():
        if not line or line.startswith('#'):
            continue
        t = line.split()
        if not t:
            continue
        name = t[0]
        if len(t) >= 2 and re.match(r'^[+-]?\d+$', t[1]):
            b = int(t[1])
            if b < 0:
                entries[name].append(SubEntry('name'))
                continue
            e = None
            if len(t) >= 3 and re.match(r'^[+-]?\d+$', t[2]):
                e = int(t[2])
            strand = t[5][0] if len(t) >= 6 and t[5] else '+'
            entries[name].append(SubEntry('region', b, e, strand))
        else:
            entries[name].append(SubEntry('name'))
    return entries


def cmd_subseq(argv):
    spec = {'t': False, 's': False, 'l': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'subseq')
    tab = False; strand_aware = False; line_len = 0
    for ch, val in opts:
        if ch == 't': tab = True
        elif ch == 's': strand_aware = True
        elif ch == 'l': line_len = c_atoi(val)
    if invalid or missing or len(rest) < 2:
        eprint(SUBSEQ_USAGE)
        return 1
    records = load_records(rest[0], 'stk_subseq', period=False)
    if records is None:
        return 1
    entries = parse_subseq_list(rest[1])
    if entries is None:
        eprint(f"[E::stk_subseq] failed to read the list of regions in file '{rest[1]}'\n")
        return 1
    for rec in records:
        for ent in entries.get(rec.name, []):
            L = len(rec.seq)
            region_header = (ent.kind == 'region')
            if ent.kind == 'name':
                b, e = 0, L
            else:
                b = max(0, ent.beg)
                e = L if ent.end is None or ent.end > L else ent.end
                if e < 0: e = 0
                if b >= L or e <= b:
                    continue
            seq = rec.seq[b:e]
            qual = rec.qual[b:e] if rec.qual is not None else None
            if strand_aware and ent.kind == 'region' and ent.strand == '-':
                seq = revcomp(seq)
                if qual is not None:
                    qual = qual[::-1]
            if tab:
                if strand_aware:
                    sys.stdout.write(f"{rec.name}\t{b+1}\t\n{seq}\n")
                else:
                    sys.stdout.write(f"{rec.name}\t{b+1}\t{seq}\n")
                continue
            hname = rec.name
            if region_header:
                hname = f"{rec.name}:{b+1}-{e}"
            header = hname + ((" " + rec.comment) if rec.comment else "")
            if strand_aware:
                sys.stdout.write(('@

output.arguments:
{"command":"head -n 796 seqtk_py.py > /tmp/seqtk_head.py && mv /tmp/seqtk_head.py seqtk_py.py
cat >> seqtk_py.py <<'PY'
                sys.stdout.write(('@' if rec.is_fastq else '>') + header + '\n')
                sys.stdout.write(seq + '\n')
            else:
                tmp = Record(rec.name, rec.comment, seq, qual)
                write_record(tmp, line_len=line_len, header=header)
    return 0


def trim_interval_by_quality(seq, qual, err_threshold, min_len):
    if qual is None:
        return 0, len(seq)
    best = 0.0
    cur = 0.0
    start = 0
    best_b = 0
    best_e = 0
    for i, qch in enumerate(qual):
        qv = ord(qch) - 33
        cur += err_threshold - q_error_prob(qv)
        if cur > best:
            best = cur
            best_b = start
            best_e = i + 1
        if cur < 0.0:
            cur = 0.0
            start = i + 1
    b, e = best_b, best_e
    L = len(seq)
    if min_len and e - b < min_len:
        if min_len >= L:
            b, e = 0, L
        else:
            if b > L - min_len:
                b = L - min_len
            e = b + min_len
    return b, e


def cmd_trimfq(argv):
    spec = {'q': True, 'l': True, 'b': True, 'e': True, 'L': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'trimfq')
    err_thres = 0.05
    min_len = 30
    trim_b = 0
    trim_e = 0
    retain_L = 0
    for ch, val in opts:
        if ch == 'q': err_thres = c_atof(val, 0.05)
        elif ch == 'l': min_len = c_atoi(val)
        elif ch == 'b': trim_b = c_atoi(val)
        elif ch == 'e': trim_e = c_atoi(val)
        elif ch == 'L': retain_L = c_atoi(val)
    if missing or len(rest) < 1:
        eprint(TRIMFQ_USAGE)
        return 1
    records = load_records(rest[0], 'stk_trimfq')
    if records is None:
        return 1
    fixed = (trim_b != 0 or trim_e != 0 or retain_L != 0)
    for rec in records:
        L = len(rec.seq)
        if fixed:
            b = max(0, trim_b)
            e = max(0, L - max(0, trim_e))
            if retain_L > 0:
                e = min(e, b + retain_L)
            if b > L: b = L
            if e < b: e = b
        else:
            b, e = trim_interval_by_quality(rec.seq, rec.qual, err_thres, min_len)
        seq = rec.seq[b:e]
        qual = rec.qual[b:e] if rec.qual is not None else None
        tmp = Record(rec.name, rec.comment, seq, qual)
        write_record(tmp)
    return 0


