        if ch == 'n': nfiles = c_atoi(val)
        elif ch == 'l': line_len = c_atoi(val)
    if invalid or missing or len(rest) < 2:
        eprint(SPLIT_USAGE)
        return 1
    prefix, path = rest[0], rest[1]
    records = load_records(path, 'stk_split')
    if records is None:
        return 1
    if nfiles <= 0:
        nfiles = 1
    fhs = []
    try:
        for i in range(1, nfiles+1):
