            try: fh.close()
            except Exception: pass
    return 0


def hpc_seq(seq):
    out = []
    prev = None
    for ch in seq:
        u = ch.upper()
        if u != prev:
            out.append(ch)
            prev = u
    return ''.join(out)


def cmd_hpc(argv):
    path = argv[0] if argv else None
    records = load_records(path, 'stk_hpc')
    if records is None: return 1
    for rec in records:
        tmp = Record(rec.name, '', hpc_seq(rec.seq), None)
