def cmd_gap(argv):
    spec = {'l': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'gap')
    min_l = 50
    for ch, val in opts:
        if ch == 'l': min_l = c_atoi(val)
    if invalid or missing or len(rest) < 1:
        eprint("Usage: seqtk gap [-l 50] <in.fa>\n")
        return 1
    records = load_records(rest[0], 'stk_gap')
    if records is None: return 1
    for rec in records:
        s = rec.seq
        i = 0
        while i < len(s):
            if s[i].upper() not in ('A','C','G','T'):
                j = i + 1
                while j < len(s) and s[j].upper() not in ('A','C','G','T'):
                    j += 1
                if j - i >= min_l:
                    sys.stdout.write(f"{rec.name}\t{i}\t{j}\n")
                i = j
            else:
                i += 1
    return 0


def find_N_gaps(seq, min_n):
    gaps = []
    i = 0
    while i < len(seq):
        if seq[i] in 'Nn':
            j = i + 1
            while j < len(seq) and seq[j] in 'Nn':
                j += 1
            if j - i >= min_n:
                gaps.append((i, j))
            i = j
        else:
            i += 1
    return gaps


def cmd_cutN(argv):
    spec = {'n': True, 'p': True, 'g': False}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'cutN')
    min_n = 1000
    gaps_only = False
    for ch, val in opts:
        if ch == 'n': min_n = c_atoi(val)
        elif ch == 'g': gaps_only = True
    if missing or len(rest) < 1:
        eprint(CUTN_USAGE)
        return 1
    records = load_records(rest[0], 'stk_cutN')
    if records is None: return 1
    for rec in records:
        gaps = find_N_gaps(rec.seq, min_n)
        if gaps_only:
            for b, e in gaps:
                sys.stdout.write(f"{rec.name}\t{b}\t{e}\n")
            continue
        last = 0
        for b, e in gaps:
            if b > last:
