                tmp = Record(rec.name, '', seq, None)
                write_record(tmp, force_fasta=True, header=f"{rec.name}:{last+1}-{b}")
            last = e
        if last < len(rec.seq):
            seq = rec.seq[last:]
            tmp = Record(rec.name, '', seq, None)
            write_record(tmp, force_fasta=True, header=f"{rec.name}:{last+1}-{len(rec.seq)}")
    return 0


