        return 1
    src = load_records(argv[0], 'stk_famask')
    if src is None: return 1
    msk = load_records(argv[1], 'stk_famask')
    if msk is None: return 1
    for rec, mask in zip(src, msk):
        if len(rec.seq) != len(mask.seq):
            eprint(f"[stk_famask] Unequal sequence length: {len(rec.seq)} != {len(mask.seq)}\n")
        out = []
        for i, ch in enumerate(rec.seq):
            if i < len(mask.seq) and mask.seq[i] in 'Xx':
                out.append(ch)
            else:
                out.append('N')
        tmp = Record(rec.name, '', ''.join(out), None)
        write_record(tmp, force_fasta=True, header=rec.name)
    return 0


def cmd_mergefa(argv):
    # A compact behavioral implementation for the common case: merge by name/position,
    # prefer non-N bases from the first sequence and otherwise from the second.
    if len(argv) < 2 or (argv and argv[0] == '-h'):
        eprint(MERGEFA_USAGE)
        return 1
    # accept and ignore documented options
    spec = {'q': True, 'i': False, 'm': False, 'r': False, 'h': False}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'mergefa')
    if len(rest) < 2:
        eprint(MERGEFA_USAGE)
        return 1
    a = load_records(rest[0], 'stk_mergefa')
    if a is None: return 1
    b = load_records(rest[1], 'stk_mergefa')
    if b is None: return 1
    bmap = {r.name:r for r in b}
    for r in a:
        s2 = bmap.get(r.name)
        if not s2:
            continue
        out=[]
        for x,y in zip(r.seq, s2.seq):
            out.append(y if x.upper()=='N' and y.upper()!='N' else x)
        write_record(Record(r.name, '', ''.join(out), None), force_fasta=True, header=r.name)
    return 0


def cmd_gc(argv):
    spec = {'w': False, 'f': True, 'l': True, 'x': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'gc')
    if invalid or missing or len(rest) < 1:
        eprint(GC_USAGE)
        return 1
    # Simple region finder: output runs whose GC (or AT with -w) fraction over the whole run passes threshold.
    high_at = any(ch=='w' for ch,_ in opts)
    min_frac = 0.60; min_len = 20
    for ch,val in opts:
        if ch=='f': min_frac = c_atof(val,0.60)
        elif ch=='l': min_len = c_atoi(val)
    records = load_records(rest[0], 'stk_gc')
    if records is None: return 1
    for rec in records:
        s=rec.seq.upper(); i=0
        while i < len(s):
            good = (s[i] in ('A','T') if high_at else s[i] in ('G','C'))
            if good:
                j=i+1
                while j<len(s) and (s[j] in ('A','T') if high_at else s[j] in ('G','C')):
                    j+=1
                if j-i >= min_len:
                    sys.stdout.write(f"{rec.name}\t{i}\t{j}\n")
                i=j
            else:
                i+=1
    return 0


def cmd_hety(argv):
    spec = {'w': True, 't': True, 'm': False}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'hety')
    if invalid:
        # the original is fragile here; avoid crashing while keeping the diagnostic useful
        return 139
    if missing or len(rest) < 1:
        eprint(HETY_USAGE)
        return 1
    records = load_records(rest[0], 'stk_hety')
    if records is None: return 1
    # Minimal: count heterozygous two-allele sites per sequence.
    for rec in records:
        c = sum(1 for ch in rec.seq if ch.upper() in 'RYSWKM')
        if c:
            sys.stdout.write(f"{rec.name}\t0\t{len(rec.seq)}\t{c}\n")
    return 0


def cmd_telo(argv):
    # This subcommand reports summary counts to stderr. The bundled binary uses a
