def main(argv):
    if len(argv) < 2:
        eprint(MAIN_USAGE)
        return 1
    cmd = argv[1]
    args = argv[2:]
    dispatch = {
        'seq': cmd_seq,
        'size': cmd_size,
        'comp': cmd_comp,
        'sample': cmd_sample,
        'subseq': cmd_subseq,
        'fqchk': cmd_fqchk,
        'mergepe': cmd_mergepe,
        'split': cmd_split,
        'trimfq': cmd_trimfq,
        'hpc': cmd_hpc,
        'dropse': cmd_dropse,
        'rename': cmd_rename,
        'gap': cmd_gap,
        'cutN': cmd_cutN,
        'listhet': cmd_listhet,
        'randbase': cmd_randbase,
        'mutfa': cmd_mutfa,
        'famask': cmd_famask,
        'mergefa': cmd_mergefa,
        'gc': cmd_gc,
        'hety': cmd_hety,
        'telo': cmd_telo,
    }
    if cmd not in dispatch:
        eprint(f"[main] unrecognized command '{cmd}'. Abort!\n")
