def trim_interval_by_quality(seq, qual, err_threshold, min_len):
    if qual is None:
        return 0, len(seq)
    best = 0.0
    cur = 0.0
    start = 0
    best_b = 0
    best_e = 0
    for i, qch in enumerate(qual):
        qv = ord(qch) - 33
        cur += err_threshold - q_error_prob(qv)
        if cur > best:
            best = cur
            best_b = start
            best_e = i + 1
        if cur < 0.0:
            cur = 0.0
            start = i + 1
    b, e = best_b, best_e
    L = len(seq)
    if min_len and e - b < min_len:
        if min_len >= L:
            b, e = 0, L
        else:
            if b > L - min_len:
                b = L - min_len
            e = b + min_len
    return b, e


def cmd_trimfq(argv):
    spec = {'q': True, 'l': True, 'b': True, 'e': True, 'L': True}
    opts, rest, invalid, missing = parse_short_options(argv, spec, 'trimfq')
    err_thres = 0.05
    min_len = 30
    trim_b = 0
    trim_e = 0
    retain_L = 0
    for ch, val in opts:
        if ch == 'q': err_thres = c_atof(val, 0.05)
        elif ch == 'l': min_len = c_atoi(val)
        elif ch == 'b': trim_b = c_atoi(val)
        elif ch == 'e': trim_e = c_atoi(val)
        elif ch == 'L': retain_L = c_atoi(val)
    if missing or len(rest) < 1:
        eprint(TRIMFQ_USAGE)
        return 1
    records = load_records(rest[0], 'stk_trimfq')
    if records is None:
        return 1
    fixed = (trim_b != 0 or trim_e != 0 or retain_L != 0)
    for rec in records:
        L = len(rec.seq)
        if fixed:
            b = max(0, trim_b)
            e = max(0, L - max(0, trim_e))
            if retain_L > 0:
                e = min(e, b + retain_L)
            if b > L: b = L
            if e < b: e = b
        else:
            b, e = trim_interval_by_quality(rec.seq, rec.qual, err_thres, min_len)
        seq = rec.seq[b:e]
        qual = rec.qual[b:e] if rec.qual is not None else None
        tmp = Record(rec.name, rec.comment, seq, qual)
        write_record(tmp)
    return 0


