    if invalid or missing or len(rest) < 2:
        eprint(SPLIT_USAGE)
        return 1
    prefix, path = rest[0], rest[1]
    records = load_records(path, 'stk_split')
    if records is None:
        return 1
    if nfiles <= 0:
        nfiles = 1
    fhs = []
    try:
        for i in range(1, nfiles+1):
            fhs.append(open(f"{prefix}.{i:05d}.fa", 'w', encoding='latin-1'))
        for idx, rec in enumerate(records):
            write_record(rec, line_len=line_len, fileobj=fhs[idx % nfiles])
    finally:
        for fh in fhs:
            try: fh.close()
            except Exception: pass
    return 0


